import React, { useState } from "react";
import "./assets/style/Register.css";
import inscriptionImage from "./assets/images/maquette_desktrop/img1_inscription.png"; // Importe l'image
import "./assets/Fonts/fonts.css";

const Register = () => {
  const [name, setName] = useState("");
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [agreeTerms, setAgreeTerms] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    // Ici, tu vas appeler l'API d'inscription plus tard
  };

  return (
    <>
    <div>
    <span style={{ color: "green", fontSize: "50px" }}>Receipt</span>
    <span style={{ color: "#1653EE", fontSize: "50px" }}>Flow</span>
    </div>
    <div className="register-container">
      <div className="register-image">
        <img src={inscriptionImage} alt="Inscription" />
      </div>
      <div className="register-box">
      
        <h2>
          <span style={{ fontFamily: "Pacifico, cursive",fontSize:'35px' }}>Sign Up to </span>
          <span style={{ fontFamily: "Pacifico, cursive" }}>
            {" "}
            <span style={{ color: "green", fontSize: "37px" }}>Receipt</span>
            <span style={{ color: "#1653EE", fontSize: "37px" }}>Flow</span>
          </span>
        </h2>
        <form onSubmit={handleSubmit}>
          <input
            required
            type="text"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <input
            required
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <input
            required
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <input
            required
            minLength={6}
            type="password"
            placeholder="6+ Characters "
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <div className="terms">
            <input
              type="checkbox"
              id="agreeTerms"
              checked={agreeTerms}
              onChange={(e) => setAgreeTerms(e.target.checked)}
            />
            <label htmlFor="agreeTerms">
              I agree with ReceiptFlow's Terms of Service, Privacy Policy, and
              default Notification Settings
            </label>
          </div>
          <button type="submit" className="create-account-button">
            Create Account
          </button>
        </form>
      </div>
    </div>
    </>
  );
};

export default Register;
